"""
A computational search for Molien-indistinguishable pairs of group actions.

The rigidity theorem says: for two actions of groups of the same order, either the
fixed-point q-series coincide, or the orbit-counting sequences already differ at some
degree n <= max(|X|,|Y|).  There is no middle ground.  This script tests that
dichotomy exhaustively on all subgroups of the symmetric groups on up to 4 points,
and exhibits the resulting collision classes.

What it demonstrates:

  * every pair of same-order actions whose orbit counts agree for n <= |X| in fact
    agrees in every degree we test (no "late divergence" is ever found);
  * the collision classes are exactly the classes of equal fixed-point multisets;
  * concrete non-isomorphic groups with identical invariants show up automatically --
    for instance the two regular actions of order 4 (cyclic versus Klein), which are
    indistinguishable in every degree.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import combinations, permutations
from typing import Dict, List, Sequence, Tuple

Perm = Tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[q[i]] for i in range(len(p)))


def closure(gens: Sequence[Perm], degree: int) -> Tuple[Perm, ...]:
    identity: Perm = tuple(range(degree))
    seen = {identity}
    frontier = [identity]
    while frontier:
        nxt: List[Perm] = []
        for element in frontier:
            for g in gens:
                cand = compose(g, element)
                if cand not in seen:
                    seen.add(cand)
                    nxt.append(cand)
        frontier = nxt
    return tuple(sorted(seen))


def all_subgroups(degree: int) -> List[Tuple[Perm, ...]]:
    """All subgroups of Sym(degree), found by closing every set of <= 2 generators."""
    elements = list(permutations(range(degree)))
    found: Dict[Tuple[Perm, ...], None] = {}
    for g in elements:
        found[closure([g], degree)] = None
    for g, h in combinations(elements, 2):
        found[closure([g, h], degree)] = None
    return sorted(found, key=lambda grp: (len(grp), grp))


def fibres(group: Sequence[Perm], degree: int) -> Tuple[int, ...]:
    counts = [0] * (degree + 1)
    for p in group:
        counts[sum(1 for i, im in enumerate(p) if im == i)] += 1
    return tuple(counts)


def orbit_counts(group: Sequence[Perm], degree: int, upto: int) -> Tuple[int, ...]:
    order = len(group)
    fib = fibres(group, degree)
    return tuple(sum(f * v ** n for v, f in enumerate(fib)) // order
                 for n in range(upto + 1))


def density(group: Sequence[Perm], degree: int) -> Tuple[Fraction, ...]:
    order = len(group)
    return tuple(Fraction(f, order) for f in fibres(group, degree))


def main() -> None:
    degree = 4
    groups = all_subgroups(degree)
    print(f"All subgroups of Sym({degree}) found by 2-generator closure: {len(groups)}")

    window = degree            # the theorem's window: n <= max(|X|,|Y|)
    horizon = 25               # far beyond the window, to look for late divergence

    late_divergence = 0
    checked = 0
    classes: Dict[Tuple[Fraction, ...], List[Tuple[Perm, ...]]] = {}

    for group in groups:
        classes.setdefault(density(group, degree), []).append(group)

    for a, b in combinations(groups, 2):
        short_a = orbit_counts(a, degree, window)
        short_b = orbit_counts(b, degree, window)
        if short_a != short_b:
            continue
        checked += 1
        long_a = orbit_counts(a, degree, horizon)
        long_b = orbit_counts(b, degree, horizon)
        if long_a != long_b:
            late_divergence += 1
        # the theorem also predicts equal densities
        assert density(a, degree) == density(b, degree)

    print(f"pairs agreeing on the first {window + 1} orbit counts: {checked}")
    print(f"of those, pairs that later diverge (n <= {horizon}): {late_divergence}")
    print("(the dichotomy predicts 0)")

    print("\nCollision classes with more than one subgroup, by fixed-point density:")
    for dens, members in sorted(classes.items(), key=lambda kv: -len(kv[1])):
        if len(members) < 2:
            continue
        orders = sorted({len(m) for m in members})
        print(f"  rho = {[str(x) for x in dens]}   "
              f"{len(members)} subgroups, orders {orders}")

    print("\nThe regular blind spot, checked directly:")
    c4 = closure([(1, 2, 3, 0)], 4)
    v4 = closure([(1, 0, 3, 2), (2, 3, 0, 1)], 4)
    print(f"  Z/4      : fibres {fibres(c4, 4)}   counts {orbit_counts(c4, 4, 6)}")
    print(f"  Z/2 x Z/2: fibres {fibres(v4, 4)}   counts {orbit_counts(v4, 4, 6)}")
    print("  identical in every tested degree, yet the groups are not isomorphic:")
    print(f"  element orders in Z/4      : "
          f"{sorted(order_of(p) for p in c4)}")
    print(f"  element orders in Z/2 x Z/2: "
          f"{sorted(order_of(p) for p in v4)}")


def order_of(p: Perm) -> int:
    identity = tuple(range(len(p)))
    current, k = p, 1
    while current != identity:
        current = compose(p, current)
        k += 1
    return k


if __name__ == "__main__":
    main()
